<?php
session_start();if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}require_once __DIR__.'/../config/db.php';if(!$pdo)die('Ma’lumotlar bazasi bilan ulanish yo‘q.');require_once __DIR__.'/../config/schema_compat.php';
$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$duration=trim($_POST['duration']??'');$description=trim($_POST['description']??'');$teacher=trim($_POST['teacher_name']??'');$teacherBio=trim($_POST['teacher_bio']??'');$image=trim($_POST['image_path']??'');$teacherImage=trim($_POST['teacher_image']??'');$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);
if($name===''||mb_strlen($name)>120||$price===false||$price===null||$price<0){header('Location: courses.php?msg=error');exit;}
try{if($id>0){$q=$pdo->prepare('UPDATE courses SET name=?,price=?,duration=?,description=?,teacher_name=?,teacher_bio=?,image_path=?,teacher_image=?,is_active=? WHERE id=?');$q->execute([$name,$price,$duration?:null,$description?:null,$teacher?:null,$teacherBio?:null,$image?:null,$teacherImage?:null,isset($_POST['is_active'])?1:0,$id]);}else{$q=$pdo->prepare('INSERT INTO courses(name,price,duration,description,teacher_name,teacher_bio,image_path,teacher_image,is_active) VALUES(?,?,?,?,?,?,?,?,1)');$q->execute([$name,$price,$duration?:null,$description?:null,$teacher?:null,$teacherBio?:null,$image?:null,$teacherImage?:null]);}header('Location: courses.php?msg=saved');exit;}catch(Throwable $e){error_log('Algoritm course save failed: '.$e->getMessage());header('Location: courses.php?msg=error');exit;}
